{
  "scope": {
    "project": "/work/Demo",
    "mode": "仅依据题设作描述性推演；全部回执均为 mock，未执行任何审计、恢复、派发或资源释放操作。",
    "source_limit": "只读取了指定 case 输入；未加载 Skill、查询实际配置或核验原件。下述决定不是实际运行状态的证明。"
  },
  "decision": {
    "summary": "当前不能进入下一轮，也不能宣告恢复成功。只可沿原链继续恢复证据与核验状态，不能重新启动调用。较晚终态原件经原链核验通过后，可以解除对应调用的资源阻塞，但不自动改变旧审计结论或授权下一轮。",
    "effective_dispatch_allowed_now": false,
    "reason": "同 cycle 此前 attempt 的 auxiliary 调用 checker-old 仍为 unknown。audit-old 已终态，只能说明该审计调用自身结束，不能证明辅助调用也已结束。有效票、PASS 与 next_round_dispatch_allowed=true 不能替代尚缺的资源终态证明。这里的 false 是本次推演的派发决定，并非已修改原字段。"
  },
  "recovery": {
    "decision": "保持受阻的恢复待核验状态，不补发、不猜测恢复标识。",
    "resume_only": "题设中的 resume_only=true 应作为只能恢复既有执行的限制，而不是再运行一次的许可；该 mock 字段本身不能证明原调用已恢复或已经结束。",
    "missing_original_receipt": "原工具回执暂找不到，不能凭当前 build 回执拼造原工具输出、调用身份或恢复参数。可以描述沿原 cycle、build、attempt 与 runId 关联查回原件的恢复步骤，但在原链身份及恢复入口得到可验证证明之前，不宣告能够实际恢复执行。本次不执行这些步骤。",
    "history": "恢复时必须保留此前 attempt 的 checker-old 未决项；创建新 attempt 或恢复当前 build，均不能使该历史调用自动消失。"
  },
  "dispatch": {
    "current": "禁止下一轮新增审计或辅助调用；不能仅按 next_round_dispatch_allowed=true 派发。审计内容结论与资源可用性须分开判断。",
    "new_cycle_proposal": "不接受新建 cycle 补一次作为绕过方案。题设没有证明旧调用已结束，也没有提供允许隔离执行的规则；换 cycle 标识不等于消除未决资源占用，不能借此重复启动。",
    "timeout_proposal": "不接受按 120 秒已过释放槽并重发。经过一段时间不构成终态证据；超时或失联应保留 unknown。即使提出取消，也必须有对应调用实际终止的可核验证据，不能把取消意图视为已释放。",
    "after_verified_terminal": "只有 checker-old 的终态原件通过原链复核，且该 cycle 各 attempt 不再有其他未决资源调用，才可重新判断资源条件。还需复核当前恢复阶段、其余守卫与下一轮派发条件；resume_only 的限制不能被资源终态自动覆盖。不得从一份终态原件直接推导下一轮已经获准或已经执行。"
  },
  "evidence": {
    "later_original_status": "题设称另一分支提供了较晚的同调用资源终态原件，但本输入未附原件；目前只能将其列为待原链核验材料，不能视为已核验通过。",
    "proposed_checks": [
      "核对原件确实归属 /work/Demo 的原 cycle、原 attempt/build 关联和 auxiliary 调用 checker-old，而不是 audit-old 或同名新调用。",
      "核对原件来源、实际工具调用身份与终态时间顺序，确认它是对应调用的资源终态证据，而非分支摘要、派生报告、内容 PASS 或超时推断。具体绑定字段与真实性校验方法未提供，不能虚构已完成校验。",
      "确认记录足以证明对应资源调用结束；若只有审计内容完成、部分子任务完成或含糊的完成描述，仍不能据此释放整个调用占用。"
    ],
    "on_success": "将经核验的较晚终态证据关联回原调用历史，更新对应的资源核验状态；保留此前 unknown 的历史记录及新证据来源，不把后来的终态倒写成早先已知。资源占用可按核验后的终态解除，是否重试或继续仍须独立判断。终态不必然代表成功。",
    "on_failure": "原链关联不足、原件不完整或存在冲突时，继续保持 checker-old 为 unknown 并阻止新增派发；不以跨分支声称替代核验。",
    "immutable_content": "旧 C、raw、有效票与既有 PASS 保持不变；较晚资源终态只处理资源状态，不用于补造内容证据、改票、重算旧结论或将过去受阻的派发追认为合法。若发现实际内容链有问题，应另记问题，不静默篡改旧产物。"
  },
  "unknowns_and_assumptions": {
    "assumptions": [
      "将题设的守卫 true 理解为启用资源安全守卫；不为推进流程自行关闭或降级。",
      "按题设接受已有票有效及 PASS 的内容结论，但将它们与资源终态、执行恢复和派发许可区分。"
    ],
    "unknowns": [
      "未提供实际 Skill 规则、完整守卫定义、资源容量模型及 resume_only 的精确执行接口，不能给出有来源保证的命令、字段契约或自动解锁算法。",
      "未提供原 cycle/build/attempt 的具体标识、原工具回执、较晚终态原件、完整调用清单或其他派发门状态，不能确认原链匹配、全部资源已清理或恢复条件已满足。",
      "next_round_dispatch_allowed=true 是否为过时计算结果、是否覆盖资源条件，以及本次终态属于成功、失败还是取消，均未获证明；这些未知不构成放行理由。"
    ]
  }
}
